  ffi.Pointer<BIO> bio,
  ffi.Pointer<ffi.Pointer<ffi.Char>> out_name,
  ffi.Pointer<ffi.Pointer<ffi.Char>> out_header,
  ffi.Pointer<ffi.Pointer<ffi.Uint8>> out_data,
  ffi.Pointer<ffi.Long> out_len,
);

