typedef NOTICEREF = NOTICEREF_st;

/// A NOTICEREF represents a NoticeReference structure (RFC 5280).
final class NOTICEREF_st extends ffi.Struct {
  external ffi.Pointer<ASN1_STRING> organization;

  external ffi.Pointer<stack_st_ASN1_INTEGER> noticenos;

  static ffi.Pointer<NOTICEREF_st> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ASN1_STRING> organization,
    required ffi.Pointer<stack_st_ASN1_INTEGER> noticenos,
  }) => $allocator<NOTICEREF_st>()
    ..ref.organization = organization
    ..ref.noticenos = noticenos;
}

/// A Netscape_spkac_st, or `NETSCAPE_SPKAC`, represents a PublicKeyAndChallenge
/// structure. This type is misnamed. The full SPKAC includes the signature,
/// which is represented with the `NETSCAPE_SPKI` type.
final class Netscape_spkac_st extends ffi.Struct {
  external ffi.Pointer<X509_PUBKEY> pubkey;

  external ffi.Pointer<ASN1_IA5STRING> challenge;

  static ffi.Pointer<Netscape_spkac_st> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<X509_PUBKEY> pubkey,
    required ffi.Pointer<ASN1_IA5STRING> challenge,
  }) => $allocator<Netscape_spkac_st>()
    ..ref.pubkey = pubkey
    ..ref.challenge = challenge;
}

/// A Netscape_spki_st, or `NETSCAPE_SPKI`, represents a
/// SignedPublicKeyAndChallenge structure. Although this structure contains a
/// `spkac` field of type `NETSCAPE_SPKAC`, these are misnamed. The SPKAC is the
/// entire structure, not the signed portion.
final class Netscape_spki_st extends ffi.Struct {
  external ffi.Pointer<NETSCAPE_SPKAC> spkac;

  external ffi.Pointer<X509_ALGOR> sig_algor;

  external ffi.Pointer<ASN1_BIT_STRING> signature;

  static ffi.Pointer<Netscape_spki_st> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<NETSCAPE_SPKAC> spkac,
    required ffi.Pointer<X509_ALGOR> sig_algor,
    required ffi.Pointer<ASN1_BIT_STRING> signature,
  }) => $allocator<Netscape_spki_st>()
    ..ref.spkac = spkac
    ..ref.sig_algor = sig_algor
    ..ref.signature = signature;
}

