typedef uint_fast64_t = ffi.UnsignedLong;
typedef Dartuint_fast64_t = int;
typedef uint_fast8_t = ffi.UnsignedChar;
typedef Dartuint_fast8_t = int;
typedef uint_least16_t = __uint_least16_t;
typedef uint_least32_t = __uint_least32_t;
typedef uint_least64_t = __uint_least64_t;
typedef uint_least8_t = __uint_least8_t;
typedef uintmax_t = __uintmax_t;
typedef ulong = ffi.UnsignedLong;
typedef Dartulong = int;
typedef ushort = ffi.UnsignedShort;
typedef Dartushort = int;

/// v3_ext_ctx, aka `X509V3_CTX`, contains additional context information for
/// constructing extensions. Some string formats reference additional values in
/// these objects. It must be initialized with `X509V3_set_ctx` or
/// `X509V3_set_ctx_test` before use.
final class v3_ext_ctx extends ffi.Struct {
  @ffi.Int()
  external int flags;

  external ffi.Pointer<X509> issuer_cert;

  external ffi.Pointer<X509> subject_cert;

  external ffi.Pointer<X509_REQ> subject_req;

  external ffi.Pointer<X509_CRL> crl;

  external ffi.Pointer<CONF> db;

  static ffi.Pointer<v3_ext_ctx> $allocate(
    ffi.Allocator $allocator, {
    required int flags,
    required ffi.Pointer<X509> issuer_cert,
    required ffi.Pointer<X509> subject_cert,
    required ffi.Pointer<X509_REQ> subject_req,
    required ffi.Pointer<X509_CRL> crl,
    required ffi.Pointer<CONF> db,
  }) => $allocator<v3_ext_ctx>()
    ..ref.flags = flags
    ..ref.issuer_cert = issuer_cert
    ..ref.subject_cert = subject_cert
    ..ref.subject_req = subject_req
    ..ref.crl = crl
    ..ref.db = db;
}

/// A v3_ext_method, aka `X509V3_EXT_METHOD`, is a deprecated type which defines
/// a custom extension.
final class v3_ext_method extends ffi.Struct {
  /// ext_nid is the NID of the extension.
  @ffi.Int()
  external int ext_nid;

  /// ext_flags is a combination of `X509V3_EXT_*` constants.
  @ffi.Int()
  external int ext_flags;

  /// it determines how values of this extension are allocated, released, parsed,
  /// and marshalled. This must be non-NULL.
  external ffi.Pointer<ASN1_ITEM_EXP> it;

  /// The following functions are ignored in favor of `it`. They are retained in
  /// the struct only for source compatibility with existing struct definitions.
  external X509V3_EXT_NEW ext_new;

  external X509V3_EXT_FREE ext_free;

  external X509V3_EXT_D2I d2i;

  external X509V3_EXT_I2D i2d;

  /// The following functions are used for string extensions.
  external X509V3_EXT_I2S i2s;

  external X509V3_EXT_S2I s2i;

  /// The following functions are used for multi-valued extensions.
  external X509V3_EXT_I2V i2v;

  external X509V3_EXT_V2I v2i;

  /// The following functions are used for "raw" extensions, which implement
  /// custom printing behavior.
  external X509V3_EXT_I2R i2r;

  external X509V3_EXT_R2I r2i;

  /// Any extension specific data
  external ffi.Pointer<ffi.Void> usr_data;

  static ffi.Pointer<v3_ext_method> $allocate(
    ffi.Allocator $allocator, {
    required int ext_nid,
    required int ext_flags,
    required ffi.Pointer<ASN1_ITEM_EXP> it,
    required X509V3_EXT_NEW ext_new,
    required X509V3_EXT_FREE ext_free,
    required X509V3_EXT_D2I d2i,
    required X509V3_EXT_I2D i2d,
    required X509V3_EXT_I2S i2s,
    required X509V3_EXT_S2I s2i,
    required X509V3_EXT_I2V i2v,
    required X509V3_EXT_V2I v2i,
    required X509V3_EXT_I2R i2r,
    required X509V3_EXT_R2I r2i,
    required ffi.Pointer<ffi.Void> usr_data,
  }) => $allocator<v3_ext_method>()
    ..ref.ext_nid = ext_nid
    ..ref.ext_flags = ext_flags
    ..ref.it = it
    ..ref.ext_new = ext_new
    ..ref.ext_free = ext_free
    ..ref.d2i = d2i
    ..ref.i2d = i2d
    ..ref.i2s = i2s
    ..ref.s2i = s2i
    ..ref.i2v = i2v
    ..ref.v2i = v2i
    ..ref.i2r = i2r
    ..ref.r2i = r2i
    ..ref.usr_data = usr_data;
}

